-- Consulta independente após publicação. Somente leitura.
with requested as(select jsonb_array_elements_text('["constitucional-direitos-fundamentais-teoria-geral", "constitucional-vida-igualdade", "constitucional-liberdades-constitucionais", "constitucional-propriedade-funcao-social", "constitucional-seguranca-juridica-processo", "constitucional-remedios-constitucionais", "constitucional-direitos-sociais-trabalho", "constitucional-organizacao-estado-competencias", "constitucional-administracao-publica-constituicao", "constitucional-judiciario-garantias-carreira", "constitucional-tribunais-competencias-cnj", "constitucional-funcoes-essenciais-justica", "constitucional-principios-fundamentais-federacao-republica", "constitucional-nacionalidade-medidas-retirada", "constitucional-direitos-politicos-elegibilidade"]'::jsonb) as slug)
select jsonb_build_object(
 'materials',(select jsonb_agg(to_jsonb(m)) from public.study_materials m join requested r on r.slug=m.slug),
 'enrichments',(select jsonb_agg(to_jsonb(e)) from public.study_material_enrichments e join requested r on r.slug=e.material_slug),
 'sources',(select jsonb_agg(jsonb_build_object('url',s.url,'is_official',s.is_official,'status',s.status)) from public.content_sources s where s.url in ('https://www.planalto.gov.br/ccivil_03/Constituicao/ConstituicaoCompilado.htm','https://conhecimento.fgv.br/sites/default/files/concursos/edital_delegado.22.12_0.pdf','https://www.planalto.gov.br/ccivil_03/Leis/L9507.htm','https://www.planalto.gov.br/ccivil_03/_Ato2015-2018/2016/Lei/L13300.htm','https://www.planalto.gov.br/ccivil_03/_Ato2007-2010/2009/Lei/L12016.htm','https://portal.stf.jus.br/jurisprudencia/sumariosumulas.asp?base=26&sumula=1268')),
 'valid_practice_syllabus',(select count(*) from public.study_materials m join requested r on r.slug=m.slug join public.syllabus_topics t on t.id=(m.practice_review->>'syllabus_topic_id')::uuid join public.syllabus_editions se on se.id=t.edition_id where t.content_status='current' and se.status='active')
) as data;
